import { IntlShape } from 'react-intl';

import { RelatedAnalysisCardProps } from './RelatedAnalysisCard';

type MessageIds = {
  title: string;
  description: string;
  descriptionFromContext?: string;
  buttonLabel: string;
  warning: string;
  warningFromContext?: string;
};

type BuildOptions = {
  formatMessage: IntlShape['formatMessage'];
  messages: MessageIds;
  isFromContext?: boolean;
};

export const buildRelatedAnalysisCardProps = ({
  formatMessage,
  messages,
  isFromContext = false,
}: BuildOptions): Pick<
  RelatedAnalysisCardProps,
  'title' | 'description' | 'buttonLabel' | 'warning'
> => ({
  title: formatMessage({ id: messages.title }),
  description: formatMessage({
    id:
      isFromContext && messages.descriptionFromContext
        ? messages.descriptionFromContext
        : messages.description,
  }),
  buttonLabel: formatMessage({ id: messages.buttonLabel }),
  warning: formatMessage({
    id:
      isFromContext && messages.warningFromContext
        ? messages.warningFromContext
        : messages.warning,
  }),
});
